import {Dispatch, SetStateAction, useEffect, useRef} from 'react';

type Params = {chatId: string; message: string; setMessage: Dispatch<SetStateAction<string>>};

export function useChatDraft({chatId, message, setMessage}: Params) {
  const prevChatId = useRef<string>(chatId);

  useEffect(() => {
    const draft = JSON.parse(localStorage.getItem(`draft_${chatId}`) ?? '{}');
    setMessage(draft?.text || '');
  }, [chatId, setMessage]);

  useEffect(() => {
    if (prevChatId.current !== chatId && message.trim()) {
      localStorage.setItem(`draft_${chatId}`, JSON.stringify({text: message, savedAt: Date.now()}));
    }
  }, [chatId, message]);

  useEffect(() => {
    const handleUnload = () => {
      if (message.trim())
        localStorage.setItem(
          `draft_${chatId}`,
          JSON.stringify({text: message, savedAt: Date.now()})
        );
    };

    window.addEventListener('beforeunload', handleUnload);

    return () => {
      window.removeEventListener('beforeunload', handleUnload);
    };
  }, [chatId, message]);
}

export const saveDraft = (chatId: string, draft: string) => {
  localStorage.setItem(`draft_${chatId}`, JSON.stringify({text: draft, savedAt: Date.now()}));
};

export const removeDraft = (chatId: string) => {
  localStorage.removeItem(`draft_${chatId}`);
};
